olid #283254;border-radius:20px;background:linear-gradient(145deg,#121a32aa,#0b1022);min-height:220px;transition:.25s}.cards article:hover,.modecards article:hover{transform:translateY(-5px);border-color:#6578d8}.cards i,.modecards i{display:block;font-style:normal;font-size:30px;color:#92caff;margin-bottom:20px}.cards label{display:block;font-size:9px}.cards h3{margin:12px 0}.cards .big{grid-row:span 2;min-height:460px;background:radial-gradient(at 90% 10%,#263a7566,transparent 60%),#10162a}.cards .wide{grid-column:span 2}.task{padding:13px;border:1px solid #3d4c78;border-radius:10px;margin-top:12px;color:#b9c5e5;font-size:12px}.task b{float:right;color:#8dd5ff}.chips{display:flex;gap:8px;margin-top:22px;flex-wrap:wrap}.chips span{border:1px solid #4b5b94;border-radius:20px;padding:8px 12px;font-size:11px;color:#a6cfff}.modes{text-align:center}.modecards article{position:relative}.modecards article.chosen{border-color:#7767ed;background:linear-gradient(145deg,#211c4b,#10162b);box-shadow:0 0 40px #6554d51c}.modecards i{font-size:38px;margin:20px 0}.modecards small{color:#8caaff;letter-spacing:2px;font-size:9px}.chatrow{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;margin-top:30px}.chatrow>div:first-child p{max-width:430px;line-height:1.8;color:#9faac8}.chatbox{padding:22px;border:1px solid #5264a877;border-radius:24px;background:linear-gradient(150deg,#151e3c,#0b1021);box-shadow:0 25px 80px #0003}.chatbox header{display:flex;gap:10px;align-items:center;border-bottom:1px solid #283254;padding-bottom:16px;color:#9fdcff}.chatbox header small{color:#8290b6;font-size:11px}.chatbox header span{margin-left:auto;color:#6de6ba}.bubble{padding:15px;border-radius:15px;line-height:1.6;font-size:13px;margin-top:20px;background:#161f3a;border:1px solid #3a4d83}.bubble.user{margin-left:auto;background:#283e7b;border-color:#4965b8}.bubble label{display:block;color:#8faeff;font-size:9px;letter-spacing:1px;margin-bottom:8px}.chatbox footer{font-size:10px;color:#7482a5;margin-top:20px}.philosophy{text-align:center;background:radial-gradient(ellipse at center,#20204a55,transparent 65%)}.philosophy .star{font-size:55px;color:#8c8fff;text-shadow:0 0 35px #8b66ff}.philosophy p{max-width:650px;margin:30px auto;color:#aab5d1;line-height:1.8}.philosophy>b{letter-spacing:3px}.philosophy b span{color:#a78aff}.cta{text-align:center;padding:120px 8vw;border-top:1px solid #222b49;background:radial-gradient(ellipse at center,#28205066,transparent 65%)}.cta p{color:#aab5d1;margin:25px 0 32px}.cta footer{font-size:10px;color:#697594;margin-top:25px}.bottom{border-top:1px solid #222b49;padding:30px 8vw;display:flex;align-items:center;justify-content:space-between;font-size:14px}.bottom p,.bottom a{font:12px 'DM Sans';color:#7e89a9}
