cat > script.js <<'JS'
const menu=document.querySelector('#menu');menu?.addEventListener('click',()=>{let n=document.querySelector('.mobilemenu');if(n){n.remove();return}n=document.createElement('div');n.className='mobilemenu';n.innerHTML='<a href="#visione">Esperienza</a><a href="#funzioni">Funzioni</a><a href="#modi">Modalità</a><a href="#filosofia">Filosofia</a>';Object.assign(n.style,{position:'fixed',top:'74px',left:0,right:0,padding:'24px',background:'#0b1024',display:'grid',gap:'20px',zIndex:20});document.body.append(n);n.querySelectorAll('a').forEach(a=>a.onclick=()=>n.remove())});
const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(18px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'ease-out',fill:'both'});obs.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.cards article,.values article,.modecards article,.chatbox').forEach(x=>obs.observe(x));
